'use strict';
(() => {
 const C = window.TECHPATH;
 const KEY = 'techpath.learning.v1';
 const $ = (s) => document.querySelector(s);
 const escape = (v) => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const icons = {
 home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 lessons:'<path d="M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1v15"/>',
 session:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 roadmap:'<path d="M6 3v18m0-14h10a3 3 0 0 1 0 6H9a3 3 0 0 0 0 6h9"/><circle cx="6" cy="4" r="2"/><path d="m16 17 2 2-2 2"/>',
 notebook:'<rect x="5" y="3" width="15" height="18" rx="2"/><path d="M3 7h4M3 12h4M3 17h4M10 8h6M10 12h6"/>',
 glossary:'<path d="M4 4h16v16H4zM8 15l3-7 3 7m-5-2h4M16 9v6"/>',settings:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/>'
 };
 const svg = name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${icons[name]||icons.lessons}</svg>`;
 const today = ()=>new Date().toLocaleDateString('en-CA');
 const dateLabel = d=>new Date(d).toLocaleDateString('vi-VN',{day:'numeric',month:'short',year:'numeric'});
 const uid = ()=>globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;
 const emptyState = ()=>({version:1,selected:'sql-proc',duration:60,drafts:{},attempts:[],sessions:[],notes:[],session:null,lastBackup:null,updatedAt:new Date().toISOString()});
 const validIds = new Set(C.lessons.map(l=>l.id));
 const assessmentLabels={independent:'Độc lập (lịch sử cũ)',assisted:'Có trợ giúp',retry:'Bản nháp / cần luyện',ai_pass:'AI xác nhận đạt',ai_retry:'AI: cần sửa',ai_needs_evidence:'Cần thêm bằng chứng',skipped:'Đã bỏ qua'};
 function cleanGrading(g){if(!g||!['pass','retry','needs_evidence'].includes(g.verdict))return null;const str=x=>typeof x==='string'?x.slice(0,20000):'';return {verdict:g.verdict,summary:str(g.summary),hint:str(g.hint),optimization:str(g.optimization),basis:str(g.basis),source:'ai',criteria:Array.isArray(g.criteria)?g.criteria.slice(0,20).filter(c=>c&&['met','not_met','unknown'].includes(c.status)).map(c=>({status:c.status,text:str(c.text),reason:str(c.reason)})):[]};}

 function validate(raw) {
  if(!raw || raw.version!==1 || !Array.isArray(raw.attempts)||!Array.isArray(raw.sessions)||!Array.isArray(raw.notes)||!raw.drafts||typeof raw.drafts!=='object'||Array.isArray(raw.drafts)) throw new Error('File không đúng định dạng TechPath v1.');
  const s=emptyState();
  if(raw.attempts.length>10000||raw.sessions.length>10000||raw.notes.length>10000)throw new Error('File có quá nhiều bản ghi.');
  const str=(x,max=200000)=>typeof x==='string'?x.slice(0,max):'';
  s.selected=validIds.has(raw.selected)?raw.selected:'sql-proc';
  s.duration=Number.isInteger(raw.duration)&&raw.duration>=15&&raw.duration<=240?raw.duration:60;
  for(const [k,v] of Object.entries(raw.drafts))if(validIds.has(k)&&v&&typeof v==='object')s.drafts[k]={code:str(v.code),output:str(v.output),notes:str(v.notes),question:str(v.question),hints:Math.min(3,Math.max(0,Number(v.hints)||0)),solution:!!v.solution,mode:v.mode==='transfer'?'transfer':'standard',checks:Array.isArray(v.checks)?v.checks.map(Boolean).slice(0,10):[]};
  s.attempts=raw.attempts.filter(a=>a&&validIds.has(a.lessonId)&&!isNaN(Date.parse(a.at))).map(a=>({id:str(a.id,80)||uid(),lessonId:a.lessonId,at:a.at,code:str(a.code),output:str(a.output),notes:str(a.notes),question:str(a.question),hints:Math.min(3,Math.max(0,Number(a.hints)||0)),solution:!!a.solution,mode:a.mode==='transfer'?'transfer':'standard',assessment:Object.hasOwn(assessmentLabels,a.assessment)?a.assessment:'retry',grading:cleanGrading(a.grading),checks:Array.isArray(a.checks)?a.checks.map(Boolean).slice(0,10):[]}));
  s.sessions=raw.sessions.filter(x=>x&&!isNaN(Date.parse(x.at))).map(x=>({id:str(x.id,80)||uid(),at:x.at,lessonId:validIds.has(x.lessonId)?x.lessonId:'sql-proc',planned:Math.min(240,Math.max(15,Number(x.planned)||60)),minutes:Math.min(1440,Math.max(0,Number(x.minutes)||0)),reflection:str(x.reflection,10000)}));
  s.notes=raw.notes.filter(x=>x&&typeof x.text==='string'&&!isNaN(Date.parse(x.at))).map(x=>({id:str(x.id,80)||uid(),at:x.at,text:str(x.text,50000)}));
  s.lastBackup=!isNaN(Date.parse(raw.lastBackup))?raw.lastBackup:null;
  if(raw.session&&validIds.has(raw.session.lessonId)&&Number.isFinite(raw.session.elapsed)&&raw.session.elapsed>=0&&Number.isFinite(raw.session.duration)&&raw.session.duration>=15&&raw.session.duration<=240){s.session={id:str(raw.session.id,80)||uid(),lessonId:raw.session.lessonId,duration:raw.session.duration,elapsed:raw.session.elapsed,running:!!raw.session.running,started:Date.now()}; if(raw.session.running&&Number.isFinite(raw.session.started))s.session.elapsed+=Math.max(0,Date.now()-raw.session.started);}
  if(raw.tutor&&window.TechPathTutor)s.tutor=window.TechPathTutor.validate(raw.tutor);
  return s;
 }
 let state=emptyState(), storageError=false,hadLocalState=false;
 try{const saved=localStorage.getItem(KEY);if(saved){state=validate(JSON.parse(saved));hadLocalState=true;}}catch(e){storageError=true;}
 try{const hostState=window.TechPathHost?.state();if(hostState&&(!hadLocalState||Date.parse(hostState.updatedAt)>Date.parse(state.updatedAt)))state=validate(hostState);}catch{/* A malformed optional widget snapshot does not replace the local draft. */}
 const sqlRuns=new Map();let sqlBusy=false,gradeBusy=false,tutorBusy=false,progressNotice='';
 let lessonTab='learn',moduleFilter='all',lessonSearch='',notebookSearch='',vocabSearch='',reviewPacket='',saveTimer,renderedLessonId=null;
 function save(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='Đã lưu trên thiết bị này';storageError=false;}catch{$('#save-status').textContent='Chưa lưu được — hãy xuất sao lưu';storageError=true;}window.TechPathHost?.persist(state);}
 function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
 function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 async function copy(t){try{await navigator.clipboard.writeText(t);toast('Đã copy.');}catch{showModal('Copy nội dung',`<p>Trình duyệt chưa cho phép clipboard. Chọn nội dung bên dưới và copy thủ công.</p><textarea readonly>${escape(t)}</textarea>`);}}
 function showModal(title,html){$('#modal-body').innerHTML=`<h2>${escape(title)}</h2>${html}`;$('#modal').showModal();}
 const codeBlock = code=>`<div class="code-wrap"><button type="button" class="button secondary" data-copy-code>Copy</button><pre><code>${escape(code)}</code></pre></div>`;
 const moduleOf = l=>C.modules.find(m=>m.id===l.module);
 const lesson = id=>C.lessons.find(l=>l.id===id)||C.lessons[5];
 const attemptsFor=id=>state.attempts.filter(a=>a.lessonId===id);
 function status(id){const a=attemptsFor(id),ind=a.filter(x=>x.assessment==='independent');const dates=new Set(ind.map(x=>new Date(x.at).toLocaleDateString('en-CA')));if(dates.size>=2&&ind.some(x=>x.mode==='transfer'))return 'solid';if(a.some(x=>x.assessment==='ai_pass'))return 'ai_pass';if(ind.length)return 'independent';if(a.at(-1)?.assessment==='skipped')return 'skipped';if(a.length)return 'practice';return 'new';}
 const statusText=s=>({solid:'Tự làm + chuyển giao',independent:'Đã tự làm (cũ)',ai_pass:'AI xác nhận đạt',skipped:'Đã bỏ qua',practice:'Đang luyện',new:'Chưa đánh giá'}[s]);
 function draft(id){if(!state.drafts[id])state.drafts[id]={code:'',output:'',notes:'',question:'',hints:0,solution:false,mode:'standard',checks:[]};return state.drafts[id];}
 function dueLessons(){return C.lessons.filter(l=>{const a=attemptsFor(l.id).filter(x=>x.assessment!=='skipped');if(!a.length)return false;const last=a[a.length-1];const n=a.filter(x=>['independent','ai_pass'].includes(x.assessment)).length;const days=['independent','ai_pass'].includes(last.assessment)?[1,3,7,14][Math.min(Math.max(n-1,0),3)]:1;return Date.now()-Date.parse(last.at)>=days*86400000;});}
 function head(k,title,sub,extra=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;}
 const linkLesson = (l,text='Mở bài →')=>`<a class="text-link" href="#lesson/${l.id}">${escape(text)}</a>`;
 function home(){
  const l=lesson(state.selected), independent=C.lessons.filter(x=>['independent','solid','ai_pass'].includes(status(x.id))).length,minutes=state.sessions.reduce((n,s)=>n+s.minutes,0),due=dueLessons();
  return head('YOUR SPACE, YOUR PACE','Học có hướng. Tiến bộ từng bước.','Một buổi tập trung, một vấn đề hiểu rõ hơn. Hôm nay mình tiếp tục từ nơi đã dừng.',`<span class="date-tag">${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'numeric',month:'long'})}</span>`)+`
  <div class="grid-home"><div><section class="card hero"><span class="eyebrow">TIẾP TỤC HÀNH TRÌNH <span style="opacity:.4"> / </span> ${escape(moduleOf(l).name.toUpperCase())}</span><h2>${escape(l.title)}</h2><p>${escape(l.summary)}</p><div class="hero-bottom"><a class="button" href="#lesson/${l.id}">Tiếp tục học <span>↗</span></a><span class="meta">${l.minutes} phút gợi ý · Thực hành trong SSMS${l.module==='sql'?'':' / công cụ tương ứng'}</span></div></section>
  <div class="stats"><div class="stat"><span>BÀI ĐÃ ĐẠT</span><strong>${independent}<small>/ ${C.lessons.length} bài</small></strong><span class="hint">AI đánh giá theo yêu cầu bài</span></div><div class="stat"><span>THỜI GIAN TẬP TRUNG</span><strong>${Math.floor(minutes/60)}<small>giờ ${minutes%60} phút</small></strong><span class="hint">Từ các buổi đã kết thúc</span></div><div class="stat"><span>CẦN ÔN LẠI</span><strong>${due.length}<small>bài</small></strong><span class="hint">Tự làm lại trước khi xem gợi ý</span></div></div>
  <section class="card"><div class="card-title"><h2>Kỹ năng đang xây dựng</h2><a class="text-link" href="#roadmap">Toàn bộ lộ trình ↗</a></div><div class="skill-list">${C.modules.slice(0,3).map(m=>{const ls=C.lessons.filter(l=>l.module===m.id),done=ls.filter(l=>['independent','solid','ai_pass'].includes(status(l.id))).length;return `<a class="skill-row" href="#lessons/${m.id}"><span class="skill-icon">${m.icon}</span><div class="skill-body"><strong>${m.name}</strong><small>${escape(m.goal)}</small><div class="progress"><span style="width:${done/ls.length*100}%"></span></div></div><span class="meta">${done}/${ls.length} ↗</span></a>`;}).join('')}</div></section>
  <div class="section-title"><h2>Ôn để tự làm được</h2><a class="text-link" href="#lessons">Thư viện bài học →</a></div><div class="card">${due.length?due.slice(0,3).map(l=>`<div class="mini-task"><span class="bullet">↺</span><div style="flex:1"><strong>${escape(l.title)}</strong><small>Làm lại mà không mở ghi chú, rồi đánh giá bài.</small></div>${linkLesson(l)}</div>`).join(''):`<p style="margin:0">Chưa có bài đến lịch ôn. Sau lần đánh giá đầu tiên, bài sẽ quay lại sau 1 ngày; những lần độc lập tiếp theo giãn thành 3, 7 rồi 14 ngày.</p>`}</div></div>
  <aside class="right-rail"><section class="card planner"><div class="eyebrow">THIẾT KẾ BUỔI HỌC</div><h2 style="margin-top:12px">Hôm nay bạn có bao lâu?</h2><p>Kế hoạch vừa với quỹ thời gian của bạn.</p><div class="time-options">${[30,60,90,120].map(t=>`<button class="time-choice ${state.duration===t?'selected':''}" data-duration="${t}">${t}<small>PHÚT</small></button>`).join('')}</div><div class="inline-input"><input id="custom-duration" aria-label="Số phút tùy chọn" type="number" min="15" max="240" value="${state.duration}"><span class="subtle">phút · 15–240</span></div><button class="button full" style="margin-top:17px" data-start-session>${state.session?'Mở buổi đang học':'Tạo buổi học'} <span>→</span></button><p class="planner-note">Ôn nhanh · Chạy bài · Review AI</p></section>
  <section class="card"><div class="card-title"><h3>Cách học của bạn</h3><span class="pill green">CÁ NHÂN</span></div><div class="mini-task"><span class="bullet">1</span><div><strong>Tự suy luận trước</strong><small>Chỉ mở một gợi ý khi thật sự bí.</small></div></div><div class="mini-task"><span class="bullet">2</span><div><strong>Làm trong công cụ thật</strong><small>SSMS, Windows và dữ liệu thực hành.</small></div></div><div class="mini-task"><span class="bullet">3</span><div><strong>Giải thích lại cách làm</strong><small>Chuẩn bị cho tình huống và phỏng vấn.</small></div></div></section><section class="card" style="background:#1b2420"><p class="quote">“Query chạy được là bước đầu. Hiểu vì sao nó đúng mới là thứ mình giữ lại.”</p><div class="quote-label">GHI NHỚ CHO HÔM NAY</div></section></aside></div>`;
 }
 function lessonsView(filter){if(filter)moduleFilter=filter;const filtered=C.lessons.filter(l=>(moduleFilter==='all'||(moduleFilter==='skipped'?status(l.id)==='skipped':l.module===moduleFilter))&&(l.title+' '+l.summary).toLowerCase().includes(lessonSearch.toLowerCase()));return head('CURRICULUM','Thư viện bài học','Viết query, chạy trên SQL lab và để AI đánh giá theo yêu cầu; có thể bỏ qua và quay lại.')+`<input class="search" id="lesson-search" type="search" aria-label="Tìm bài học" placeholder="Tìm theo chủ đề, kỹ năng…" value="${escape(lessonSearch)}"><div class="tabs">${[{id:'all',name:'Tất cả'},{id:'skipped',name:'Đã bỏ qua'},...C.modules].map(m=>`<button class="tab ${moduleFilter===m.id?'active':''}" data-filter="${m.id}">${m.name}</button>`).join('')}</div><div class="lesson-grid">${filtered.map(l=>`<a class="card lesson-card" href="#lesson/${l.id}"><div class="lesson-index"><span>${escape(moduleOf(l).icon)} / ${String(C.lessons.indexOf(l)+1).padStart(2,'0')}</span><span class="pill ${['solid','independent','ai_pass'].includes(status(l.id))?'green':''}">${statusText(status(l.id))}</span></div><h3>${escape(l.title)}</h3><p>${escape(l.summary)}</p><div class="meta"><span>${l.minutes} phút${l.prior?' · Đã thực hành trong chat':''}</span><span>↗</span></div></a>`).join('')||'<p>Không có bài khớp từ khóa.</p>'}</div>`;}
 function lessonView(id){const l=lesson(id),d=draft(l.id);state.selected=l.id;save();return `<a class="back" href="#lessons">← Thư viện bài học</a>`+head(escape(moduleOf(l).name.toUpperCase()),escape(l.title),escape(l.summary))+`<div class="lesson-layout"><article>${progressNotice?`<div class="callout" role="status">${escape(progressNotice)}</div>`:''}<div class="lesson-title-row"><span class="pill">${l.minutes} phút gợi ý</span><span class="pill green">${statusText(status(l.id))}</span>${l.prior?'<span class="pill">Đã thực hành trong chat · Chưa xác nhận độc lập</span>':''}</div><div class="task-tabs"><button data-lesson-tab="learn" class="${lessonTab==='learn'?'active':''}">01 · Hiểu bài</button><button data-lesson-tab="practice" class="${lessonTab==='practice'?'active':''}">02 · Thực hành</button></div>
  ${lessonTab==='learn'?`<div class="card lesson-body">${l.body}<h3>Việc bạn cần giải quyết</h3><div class="callout">${escape(l.task)}</div>${l.resources.length?`<h3>Tài liệu đọc thêm</h3>${l.resources.map(r=>`<a class="resource" href="${r[1]}" target="_blank" rel="noopener">${escape(r[0])} ↗</a>`).join('')}`:''}<button class="button" data-lesson-tab="practice">Bắt đầu thực hành →</button></div>`:practice(l,d)}
  </article><aside class="sticky"><section class="card hint-card"><div class="eyebrow">MỘT BƯỚC NHỎ KHI BÍ</div><h3 style="margin-top:13px">Bạn vẫn là người giải bài.</h3><p>Đây là gợi ý soạn sẵn theo bài. Muốn hỏi đúng đoạn code đang bí, dùng “Nhờ review”.</p>${l.hints.slice(0,d.hints).map((h,i)=>`<div class="hint"><div class="hint-number">GỢI Ý ${i+1} / ${l.hints.length}</div>${escape(h)}</div>`).join('')}<button class="button secondary full" data-hint ${d.hints>=l.hints.length?'disabled':''}>${d.hints===0?'Cho mình một gợi ý':d.hints<l.hints.length?'Gợi ý thêm một chút':'Đã mở hết gợi ý'}</button><p class="save-meta">${d.hints?`Lần thử này đã dùng ${d.hints} gợi ý.`:'Chưa dùng gợi ý trong lần thử này.'}</p></section><section class="card"><h3>Bài chuyển giao</h3><p>${escape(l.transfer)}</p><button class="text-link" data-transfer>${d.mode==='transfer'?'Đang làm bài chuyển giao ✓':'Chuyển sang yêu cầu này →'}</button></section><section class="card"><h3>Môi trường thực hành</h3><p>${l.module==='sql'?'SQL Server · SQL lab riêng trong app, cùng dataset SupportLab. USE SupportLab được ánh xạ sang database lab. Mỗi máy cần chạy Start-TechPath.cmd.':'Dùng công cụ tương ứng trên máy. Lưu kết quả và cách kiểm tra vào phần thực hành.'}</p>${l.module==='sql'?'<button class="text-link" data-seed>↓ Dataset SupportLab (.sql)</button>':''}<a class="resource" href="#settings">Cấu hình gia sư ↗</a></section></aside></div>`;}
 function practice(l,d){return `<section class="card"><div class="card-title"><h2>${d.mode==='transfer'?'Bài chuyển giao':'Bài thực hành'}</h2><span class="pill">${d.mode==='transfer'?'YÊU CẦU MỚI':'TỰ SUY LUẬN'}</span></div><p>${escape(d.mode==='transfer'?l.transfer:l.task)}</p><label for="draft-code">Code / phương án của bạn</label><textarea id="draft-code" class="code-input" spellcheck="false" placeholder="Viết query tại đây. Ctrl + Enter để chạy trên SQL lab; dùng GO trên dòng riêng khi tạo procedure.">${escape(d.code)}</textarea><div class="save-meta">Tự lưu trên thiết bị · Nội dung được giữ nguyên khi đổi bài</div>${l.module==='sql'?sqlWorkspace(l,d):''}<div class="actions"><button class="button secondary" data-import-sql>↑ Nhập file .sql</button><button class="button ghost" data-download-code>↓ Tải bài làm</button><button class="button ghost" data-new-attempt>Bắt đầu lần thử mới</button></div><label for="draft-output">Kết quả / thông báo lỗi (giữ nguyên văn khi có thể)</label><textarea id="draft-output" ${l.module==='sql'?'readonly':''} placeholder="${l.module==='sql'?'Kết quả và lỗi sẽ tự điền sau khi chạy query.':'Ghi kết quả hoặc bằng chứng thực hành…'}">${escape(d.output)}</textarea><label for="draft-notes">Mình đang suy luận thế nào?</label><textarea id="draft-notes" placeholder="Mục tiêu → dữ kiện → giả thuyết → bước kiểm tra tiếp theo…">${escape(d.notes)}</textarea><label for="draft-question">Chỗ mình muốn hỏi review</label><textarea id="draft-question" placeholder="Ví dụ: Vì sao order không có payment bị mất khỏi kết quả? Chỉ gợi ý chỗ cần xem lại, đừng sửa toàn bộ code.">${escape(d.question)}</textarea>${gradingCard(attemptsFor(l.id).slice().reverse().find(a=>a.grading)?.grading)}<div class="actions"><button class="button" data-review>Review & đánh giá ↗</button><button class="button secondary" data-save-attempt>Lưu lần thử</button><button class="button ghost" data-skip>Bỏ qua bài →</button></div><p class="save-meta">AI đánh giá toàn bộ yêu cầu. Đạt: lưu kết quả và mở bài tiếp theo. Chưa đạt: nhận một gợi ý nhỏ và sửa tiếp.</p><hr class="divider"><details><summary>Xem kết quả kỳ vọng · đối chiếu sau khi tự chạy</summary><p style="margin-top:12px">${escape(l.expected)}</p></details><details id="solution"><summary>Lời giải tham khảo · bấm nút xác nhận để mở</summary><p>Xem lời giải sẽ ghi nhận lần thử hiện tại có trợ giúp.</p>${d.solution?codeBlock(l.solution):'<button class="button secondary" data-solution>Mở lời giải tham khảo</button>'}</details></section>`;}

 function planBlocks(t,l){const recap=Math.max(3,Math.min(8,Math.floor(t*.10))),learn=Math.max(2,Math.min(15,Math.floor(t*.18))),reflect=Math.max(2,Math.min(15,Math.floor(t*.12))),log=Math.max(2,Math.min(5,Math.floor(t*.08))),pause=t>=90?5:0,practice=t-recap-learn-reflect-log-pause;let blocks=[{n:'Gọi lại kiến thức',m:recap,p:dueLessons()[0]?`Ôn: ${dueLessons()[0].title}. Viết lại logic trước khi mở ghi chú.`:'Đóng ghi chú. Nhắc lại ON/WHERE, grain và một lỗi từng mắc.'},{n:'Hiểu yêu cầu',m:learn,p:`Đọc “${l.title}”. Viết mục tiêu và kết quả mong đợi bằng lời của mình.`},{n:'Thực hành tập trung',m:practice,p:'Làm trong SQL lab/công cụ của bài. Nếu bí, ghi chỗ bí và mở một gợi ý.'}];if(pause)blocks.push({n:'Nghỉ ngắn',m:pause,p:'Rời màn hình, sau đó quay lại giải thích bước đang làm.'});blocks.push({n:'Review AI / chuyển giao',m:reflect,p:'Đối chiếu kết quả, kiểm tra tình huống biên. Nếu đủ thời gian, thử yêu cầu mới.'},{n:'Ghi nhận & hẹn ôn',m:log,p:'Nhờ AI đánh giá, lưu nhận xét và ghi điều cần ôn.'});return blocks;}
 function elapsed(){const s=state.session;return s?s.elapsed+(s.running?Math.max(0,Date.now()-s.started):0):0;}
 function sessionView(){const s=state.session;if(!s)return head('FOCUS SESSION','Một buổi học vừa sức.','Chọn thời gian ở Tổng quan để tạo kế hoạch. Lịch linh hoạt theo từng ngày.')+`<section class="card empty"><h3>Chưa có buổi đang học</h3><p>30 phút vẫn đủ để hiểu rõ một vấn đề.</p><a class="button" href="#home">Thiết kế buổi học →</a></section>`;const l=lesson(s.lessonId);let p=0;return head('FOCUS SESSION',`${s.duration} phút dành cho mình`,escape(l.title))+`<div class="lesson-layout"><section class="card"><div class="card-title"><h2>Kế hoạch của buổi này</h2><span class="pill green">${s.duration} PHÚT</span></div>${planBlocks(s.duration,l).map(b=>{const range=`${p}–${p+b.m}`;p+=b.m;return `<div class="plan-block"><span class="plan-time">${range}′</span><div><h3>${escape(b.n)}</h3><p>${escape(b.p)}</p></div></div>`;}).join('')}<div class="actions"><a class="button" href="#lesson/${l.id}">Vào bài học ↗</a></div></section><aside><section class="card"><div class="eyebrow">THỜI GIAN ĐÃ TẬP TRUNG</div><div class="timer" id="timer">${formatTime(elapsed())}</div><p id="timer-note">${s.running?'Đang đếm · Có thể đổi màn hình trong app.':'Đang tạm dừng. Bấm tiếp tục khi sẵn sàng.'}</p><div class="actions"><button class="button secondary" data-pause>${s.running?'Tạm dừng':'Tiếp tục'}</button><button class="button ghost" data-finish-session>Kết thúc buổi</button></div><p class="save-meta">Đồng hồ lưu thời gian thực, không tự đánh dấu bài đã hiểu. Để tránh tính thời gian nghỉ, tạm dừng trước khi đóng app.</p></section><section class="card"><h3>Ít hơn cũng được.</h3><p>Chưa hoàn thành bài thì giữ nguyên bản nháp. Buổi sau tiếp tục; không cần chạy theo số bài.</p></section></aside></div>`;}
 function formatTime(ms){const sec=Math.floor(ms/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
 function roadmap(){return head('YOUR DIRECTION','Từ tìm lỗi đến hiểu hệ thống.','Lộ trình phục vụ Application Support / Data Operations, với SQL làm thế mạnh. Các chặng mở để bạn tự điều chỉnh.')+C.modules.map((m,i)=>`<section class="card roadmap-module"><div class="eyebrow">CHẶNG ${String(i+1).padStart(2,'0')} / ${m.tag}</div><h2>${m.name}</h2><p>${m.desc}</p><div class="roadmap-items">${C.lessons.filter(l=>l.module===m.id).map(l=>`<a href="#lesson/${l.id}"><span>${escape(l.title)}</span><span class="meta">${['ai_pass','solid','independent'].includes(status(l.id))?'✓':status(l.id)==='skipped'?'↷':'↗'}</span></a>`).join('')}</div></section>`).join('')+`<section class="card"><h3>Sau nền tảng này</h3><p>Chọn sâu hơn dựa trên công việc thực tế: Python tự động hóa, Data Engineering hoặc phân tích dữ liệu. Tiếng Nhật học riêng; tiếng Anh kỹ thuật được lồng vào thuật ngữ và ticket.</p></section>`;}
 function notebook(){const term=notebookSearch.toLowerCase();const attempts=state.attempts.slice().reverse().filter(a=>(lesson(a.lessonId).title+a.code+a.notes+a.output).toLowerCase().includes(term));return head('LEARNING JOURNAL','Lưu lại cách mình đã nghĩ.','Code, lỗi và nhận xét theo từng lần thử. Nội dung của bạn được lưu trên trình duyệt này.',`<button class="button secondary" data-export-md>↓ Xuất Markdown</button>`)+`<input type="search" class="search" id="notebook-search" placeholder="Tìm trong code, ghi chú và bài học…" aria-label="Tìm nhật ký" value="${escape(notebookSearch)}"><section class="card"><h3>Ghi chú nhanh</h3><label for="quick-note">Một phát hiện, một lỗi hay câu hỏi muốn giữ lại</label><textarea id="quick-note" placeholder="Hôm nay mình hiểu vì sao…"></textarea><button class="button secondary" style="margin-top:10px" data-add-note>Lưu ghi chú</button></section><div class="section-title"><h2>Các lần thực hành (${attempts.length})</h2><button class="text-link" data-export-md>Xuất tất cả ↗</button></div>${attempts.length?attempts.slice(0,50).map(a=>`<article class="card notebook-item"><div class="tagline"><span class="pill ${a.assessment==='independent'?'green':''}">${escape(assessmentLabels[a.assessment]||'Bản nháp')}</span><span class="meta">${dateLabel(a.at)}</span></div><h3>${escape(lesson(a.lessonId).title)}</h3>${gradingCard(a.grading)}${a.notes?`<p style="white-space:pre-wrap">${escape(a.notes)}</p>`:''}${a.code?`<details><summary>Xem bài làm đã lưu</summary>${codeBlock(a.code)}</details>`:''}${a.output?`<details><summary>Kết quả / lỗi</summary><pre class="code">${escape(a.output)}</pre></details>`:''}${linkLesson(lesson(a.lessonId),'Quay lại bài →')}</article>`).join(''):'<section class="card empty"><h3>Nhật ký bắt đầu từ một lần thử.</h3><p>Ở bài học, bấm “Lưu lần thử” hoặc đánh giá bài để lưu mốc thực hành.</p></section>'}<div class="section-title"><h2>Ghi chú cá nhân</h2></div>${state.notes.slice().reverse().filter(n=>n.text.toLowerCase().includes(term)).map(n=>`<article class="card notebook-item"><span class="meta">${dateLabel(n.at)}</span><p style="white-space:pre-wrap;margin-top:10px">${escape(n.text)}</p></article>`).join('')||'<p class="subtle">Chưa có ghi chú.</p>'}${state.sessions.length?'<div class="section-title"><h2>Buổi đã học</h2></div>'+state.sessions.slice().reverse().slice(0,10).map(s=>`<section class="card notebook-item"><span class="meta">${dateLabel(s.at)} · ${s.minutes} phút thực tế / ${s.planned} phút kế hoạch</span><h3 style="margin-top:9px">${escape(lesson(s.lessonId).title)}</h3><p style="white-space:pre-wrap">${escape(s.reflection)}</p></section>`).join(''):''}`;}
 function glossary(){return head('TECHNICAL ENGLISH','Hiểu thuật ngữ. Dùng đúng ngữ cảnh.','Giải thích tiếng Việt và thuật ngữ tiếng Anh đi cùng các bài thực hành.')+`<input class="search" id="vocab-search" type="search" aria-label="Tìm thuật ngữ" value="${escape(vocabSearch)}" placeholder="Tìm CTE, root cause, Power Query…"><div class="vocab-grid">${C.glossary.filter(t=>t.join(' ').toLowerCase().includes(vocabSearch.toLowerCase())).map(([t,d,m])=>`<article class="card"><span class="pill">${m}</span><h3 style="margin-top:13px;margin-bottom:4px">${escape(t)}</h3><p>${escape(d)}</p></article>`).join('')}</div>`;}
 const tutorPrompt=`Giúp tôi học tech bằng tiếng Việt dễ hiểu. Trả lời thẳng câu hỏi, thường 2–4 câu dưới 80 từ. Không chào, khen, nhắc lại đề hay in lại query/procedure; chỉ trích 1–3 dòng cần thiết. Chỉ gợi ý khi tôi yêu cầu. Review: một vấn đề chính, lý do, bước tiếp theo. Đúng thì xác nhận ngắn. Không ép kiểm tra kiến thức ngoài đề. Chỉ dùng code/kết quả được cung cấp. Giải thích dài khi tôi yêu cầu.`;
 function settings(){return head('WORKSPACE SETTINGS','Giữ cách học theo ý mình.','Không cần API key. Lưu cục bộ, xuất/nhập giữa PC và laptop; source code tách riêng với tiến độ cá nhân.')+`<div class="settings-grid"><section class="card"><h2>Dữ liệu & hai thiết bị</h2><p>Tiến độ nằm trong localStorage của trình duyệt và địa chỉ app hiện tại. PC và laptop không tự đồng bộ. Xuất file sau buổi học, rồi nhập ở máy còn lại.</p><div class="actions"><button class="button" data-backup>↓ Xuất sao lưu JSON</button><button class="button secondary" data-import>↑ Nhập sao lưu</button></div><p class="save-meta">${state.lastBackup?'Lần xuất gần nhất: '+dateLabel(state.lastBackup):'Chưa xuất bản sao lưu.'}</p><p class="notice">Nhập sao lưu sẽ thay thế tiến độ trên thiết bị này. App yêu cầu bạn tải bản hiện tại trước khi xác nhận. Nên giữ JSON cá nhân ngoài repository công khai.</p><button class="text-link" data-export-md>↓ Xuất nhật ký Markdown</button><hr class="divider"><h3>Dataset thực hành</h3><p>Dataset giả lập giống SupportLab đã học. Nếu đã có các bảng, script dừng và không ghi đè dữ liệu.</p><button class="button secondary" data-seed>↓ Tải SupportLab.sql</button></section>
 <section class="card"><h2>Gia sư trong TechPath</h2><p>Chạy Start-TechPath.cmd trên máy rồi dùng Nhờ review ở bài thực hành. Chạy SQL trực tiếp trong bài, rồi bấm Review & đánh giá. Đạt thì lưu nhận xét và mở bài tiếp theo; chưa đạt thì ở lại để sửa. Khung gia sư vẫn cho phép hỏi tiếp.</p><p>Hỗ trợ chọn gia sư: <strong>Gemini (Antigravity)</strong> qua 9Router hoặc <strong>Codex</strong> đã đăng nhập bằng ChatGPT. Cả hai AI dùng chung lịch sử học tập theo bài. Không cần API key thủ công; sử dụng hạn mức tài khoản kết nối.</p><p>Trình duyệt có thể hỏi quyền kết nối mạng cục bộ. Nếu bị chặn, dùng bản local ở 127.0.0.1:4173 và xuất/nhập JSON để chuyển tiến độ. Mỗi máy cần chạy bộ kết nối.</p><p class="subtle">Gia sư có lịch sử riêng theo bài và hồ sơ học của bạn. Không tự đọc SSMS hoặc toàn bộ cuộc chat thiết kế app. Chỉ gửi bài khi bạn bấm nút.</p><button class="button secondary" id="open-tutor">Mở gia sư ↗</button><hr class="divider"><h3>Tuỳ chọn riêng: Copilot trong SSMS</h3><p>Nếu dùng Copilot Chat trong SSMS, bạn có thể copy nguyên tắc gia sư bên dưới. Đây là một dịch vụ riêng, không phải nút review của TechPath.</p><button class="button secondary" data-tutor>Copy nguyên tắc gia sư</button><a class="resource" target="_blank" rel="noopener" href="https://learn.microsoft.com/en-us/ssms/github-copilot/get-started">Microsoft · Copilot trong SSMS ↗</a></section>
 <section class="card"><h2>Tiêu chí tiến bộ</h2><p>Review & đánh giá đối chiếu code, kết quả và toàn bộ yêu cầu của bài. Đạt thì app ghi “AI xác nhận đạt”, lưu nhận xét và chuyển bài; chưa đạt thì giữ bài và gợi ý nhỏ. Thiếu bằng chứng thì chưa đánh dấu đạt.</p><p>Đây là đánh giá bài thực hành bằng AI, có thể sai; không đồng nghĩa với xác nhận năng lực độc lập. Các kết quả độc lập trước đây vẫn được giữ trong nhật ký. Bỏ qua không tính là hoàn thành.</p></section><section class="card"><h2>Chi phí & source</h2><p>Phần bài học chạy độc lập. Gia sư cần bộ kết nối Codex trên máy, dùng hạn mức tài khoản ChatGPT đã đăng nhập. TechPath không dùng API key hay tự mua thêm hạn mức.</p><p>GitHub lưu source code; JSON sao lưu chứa tiến độ cá nhân. Việc push source không tự mang tiến độ sang thiết bị khác.</p><p class="subtle">TechPath v0.4 · ${C.lessons.length} bài · ${C.glossary.length} thuật ngữ</p></section></div>`;}
 function render(){const hash=location.hash.slice(1)||'home';const [page,id]=hash.split('/');let html;const map={home:'Tổng quan',lessons:'Bài học',session:'Buổi học',roadmap:'Lộ trình',notebook:'Nhật ký',glossary:'Thuật ngữ',settings:'Cài đặt'};const active=page==='lesson'?'lessons':page;$('#nav').innerHTML=Object.entries(map).filter(([k])=>k!=='settings').map(([k,v])=>`<a href="#${k}" class="${active===k?'active':''}" ${active===k?'aria-current="page"':''}>${svg(k)}<span>${v}</span></a>`).join('');$('#breadcrumb').textContent=`Workspace / ${map[active]||'Tổng quan'}`;if(page==='lesson')html=lessonView(id);else if(page==='lessons')html=lessonsView(id);else if(page==='session')html=sessionView();else if(page==='roadmap')html=roadmap();else if(page==='notebook')html=notebook();else if(page==='glossary')html=glossary();else if(page==='settings')html=settings();else html=home();$('#main').innerHTML=html;renderedLessonId=page==='lesson'?lesson(id).id:null;document.title=`${page==='lesson'?lesson(id).title:map[page]||'Tổng quan'} · TechPath`;if(storageError)$('#save-status').textContent='Không đọc/lưu được dữ liệu — hãy sao lưu';updateWorkControls();}
 function currentLesson(){return lesson(location.hash.split('/')[1]||state.selected);}
 function syncDraft(){if(!renderedLessonId)return;const d=draft(renderedLessonId);for(const k of ['code','output','notes','question']){const el=$('#draft-'+k);if(el)d[k]=el.value;}}
 function gradingCard(g){return g?`<div class="grading-result"><span class="pill ${g.verdict==='pass'?'green':'orange'}">${g.verdict==='pass'?'AI xác nhận đạt':g.verdict==='retry'?'Cần sửa':'Cần thêm bằng chứng'}</span><p>${escape(g.summary)}</p>${g.hint?'<p><strong>Gợi ý nhỏ:</strong> '+escape(g.hint)+'</p>':''}${g.optimization?'<p><strong>Cải thiện:</strong> '+escape(g.optimization)+'</p>':''}<details><summary>Tiêu chí đánh giá</summary>${g.criteria.map(c=>'<p>'+escape(c.status==='met'?'✓ ':c.status==='not_met'?'✗ ':'? ')+escape(c.text)+' — '+escape(c.reason)+'</p>').join('')}</details><p class="save-meta">${escape(g.basis)}</p></div>`:'';}
 function sqlWorkspace(l,d){const run=sqlRuns.get(l.id),stale=run&&run.code!==d.code;return `<div class="sql-workspace"><div class="actions"><button class="button" data-run-sql>▶ Chạy SQL <span class="key">Ctrl Enter</span></button><button class="button secondary" data-stop-sql hidden>Dừng SQL</button><span class="meta">SQL Server · SupportLab riêng</span></div><details><summary>Schema & dataset</summary><pre class="code">Customers: customer_id, customer_name, email (6 dòng)
Orders: order_id, customer_id, order_date, order_status, order_total (8 dòng)
Payments: payment_id, order_id, payment_date, payment_status, payment_amount (5 dòng)
Khóa chính: *_id. Không có foreign key trong lab.
Chỉ payment Succeeded là thanh toán thành công.</pre></details>${stale?'<p class="notice">Code đã thay đổi. Chạy lại để cập nhật kết quả.</p>':''}${run?sqlResult(run.result):'<p class="save-meta">Chạy query để xem bảng kết quả hoặc lỗi ngay tại đây. Hỗ trợ SELECT, CTE, GO và stored procedure trong lab.</p>'}</div>`;}
 function sqlResult(r){return `<div class="sql-result">${r.ok?'<span class="pill green">Chạy thành công</span>':'<p class="notice">'+escape(r.error?.message||'Query chưa chạy được.')+(r.error?.line?' · Dòng '+escape(r.error.line):'')+'</p>'}<span class="meta"> · ${r.elapsedMs||0} ms · ${escape(r.database||'SQL lab')}</span>${(r.results||[]).map((set,i)=>'<h3>Result '+(i+1)+' · '+set.rows.length+' dòng</h3><div class="table-wrap"><table><thead><tr>'+set.columns.map(c=>'<th>'+escape(c.name||'(không có tên)')+'</th>').join('')+'</tr></thead><tbody>'+set.rows.map(row=>'<tr>'+row.map(v=>'<td'+(v===null?' class="muted"':'')+'>'+escape(v===null?'NULL':v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>').join('')}${r.truncated?'<p class="notice">Kết quả đã giới hạn. Dùng TOP hoặc thu hẹp query trước khi đánh giá.</p>':''}</div>`;}
 function updateWorkControls(){const locked=sqlBusy||gradeBusy||tutorBusy;document.querySelectorAll('[data-run-sql],[data-review],[data-skip],[data-new-attempt],[data-transfer]').forEach(b=>b.disabled=locked);const stop=$('[data-stop-sql]');if(stop)stop.hidden=!sqlBusy;const run=$('[data-run-sql]');if(run&&sqlBusy)run.textContent='Đang chạy SQL…';const review=$('[data-review]');if(review&&gradeBusy)review.textContent='Đang đánh giá…';}
 async function runInApp(l){syncDraft();const code=draft(l.id).code;if(!code.trim())throw new Error('Viết query trước khi chạy.');sqlBusy=true;updateWorkControls();try{const result=await window.TechPathSql.run(code,l.id);sqlRuns.set(l.id,{code,result});syncDraft();if(draft(l.id).code===code)draft(l.id).output=result.output;save();if(renderedLessonId===l.id)render();return result;}finally{sqlBusy=false;updateWorkControls();}}
 function nextLesson(id){const index=C.lessons.findIndex(l=>l.id===id),ordered=[...C.lessons.slice(index+1),...C.lessons.slice(0,index)];return ordered.find(l=>!['solid','independent','ai_pass','skipped'].includes(status(l.id)));}
 function moveOn(id,reason){const next=nextLesson(id);progressNotice=reason+(next?' Đang mở: '+next.title+'.':' Xem thư viện để quay lại bài đã bỏ qua hoặc ôn tập.');save();location.hash=next?'lesson/'+next.id:'lessons';if(next)state.selected=next.id;save();render();toast(reason);}
 async function gradeAttempt(){if(sqlBusy||gradeBusy||tutorBusy)return;const l=currentLesson();syncDraft();let d=draft(l.id);if(!d.code.trim()&&!d.notes.trim()){toast('Nhập bài làm hoặc phương án để AI đánh giá.');return;}gradeBusy=true;updateWorkControls();try{if(l.module==='sql'){const run=sqlRuns.get(l.id);if(!run||run.code!==d.code)await runInApp(l);}syncDraft();d=draft(l.id);if(l.module==='sql'&&sqlRuns.get(l.id)?.code!==d.code)throw new Error('Code đã thay đổi lúc query đang chạy. Hãy bấm review lại bản hiện tại.');const snapshot=structuredClone(d),fingerprint=x=>JSON.stringify([x.code,x.output,x.notes,x.question,x.mode]),frozen=fingerprint(snapshot);const result=await window.TechPathTutor.grade({lessonId:l.id,title:l.title,prompt:packet(l.id),question:d.question,submission:{mode:d.mode,code:d.code,output:d.output,notes:d.notes,question:d.question,runId:sqlRuns.get(l.id)?.result.runId}});if(!result?.assessment)return;if(result.assessment.requiresRerun)sqlRuns.delete(l.id);syncDraft();let g=cleanGrading(result.assessment);if(!g)throw new Error('Chưa có đánh giá hợp lệ.');const changed=fingerprint(draft(l.id))!==frozen;if(changed)g={...g,verdict:'needs_evidence',summary:'Bài làm đã thay đổi trong lúc AI đánh giá. Kết quả này thuộc bản nộp trước; hãy review lại bản hiện tại.'};state.attempts.push({id:uid(),lessonId:l.id,at:new Date().toISOString(),...snapshot,assessment:g.verdict==='pass'?'ai_pass':g.verdict==='retry'?'ai_retry':'ai_needs_evidence',grading:g});save();if(renderedLessonId===l.id&&!changed&&g.verdict==='pass')moveOn(l.id,'AI xác nhận đạt: '+l.title+'.');else{progressNotice=g.summary;if(renderedLessonId===l.id)render();toast(g.verdict==='pass'?'Đã lưu kết quả đạt của bài trước.':g.verdict==='retry'?'Chưa đạt — xem gợi ý và sửa tiếp.':'Cần bổ sung bằng chứng trước khi xác nhận.');}}catch(error){toast(error.message);}finally{gradeBusy=false;updateWorkControls();}}
 function storeAttempt(assessment='retry'){syncDraft();const l=currentLesson(),d=draft(l.id);state.attempts.push({id:uid(),lessonId:l.id,at:new Date().toISOString(),...structuredClone(d),assessment});save();}
 function packet(id){
  syncDraft();const l=id?lesson(id):currentLesson(),d=draft(l.id);
  return [`Bài: ${l.title}\nYêu cầu: ${d.mode==='transfer'?l.transfer:l.task}`,
   l.module==='sql'?'SQL Server / SupportLab: Customers(customer_id PK,customer_name,email NULL); Orders(order_id PK,customer_id,order_date,order_status,order_total); Payments(payment_id PK,order_id,payment_date NULL,payment_status,payment_amount). Một order có nhiều payment; chỉ Succeeded thành công.':'Môi trường: Windows / công cụ của bài.',
   `Bài làm:\n${d.code||'(chưa có)'}`,d.output&&`Kết quả / lỗi:\n${d.output}`,d.notes&&`Ghi chú:\n${d.notes}`,`Câu hỏi: ${d.question||'Review bài làm.'}`].filter(Boolean).join('\n\n');
 }
 window.TechPathTutorContext=()=>{const l=currentLesson();return {lessonId:l.id,title:l.title,prompt:packet(),question:draft(l.id).question};};
 function backup(){syncDraft();state.lastBackup=new Date().toISOString();save();download(`techpath-backup-${today()}.json`,JSON.stringify({...state,tutor:window.TechPathTutor?.export()},null,2),'application/json');toast('Đã xuất tiến độ. Giữ file để nhập trên máy khác.');}
 function exportMd(){syncDraft();const md=['# TechPath — Learning journal',`Exported: ${new Date().toISOString()}`,'',...state.attempts.map(a=>`## ${lesson(a.lessonId).title}\n\n${a.at} · ${a.assessment} · ${a.mode}\n\n### Bài làm\n\n\`\`\`sql\n${a.code.replace(/```/g,'` ` `')}\n\`\`\`\n\n### Kết quả\n\n${a.output}\n\n### Ghi chú\n\n${a.notes}\n\n### AI review\n\n${a.grading?[a.grading.verdict,a.grading.summary,a.grading.hint,a.grading.optimization,...a.grading.criteria.map(c=>c.status+": "+c.text+" — "+c.reason),a.grading.basis].filter(Boolean).join("\n\n"):"Chưa có đánh giá AI."}\n`),'## Ghi chú riêng','',...state.notes.map(n=>`${n.at}\n\n${n.text}\n`),'## Buổi học','',...state.sessions.map(s=>`${s.at} · ${s.minutes} phút\n\n${s.reflection}\n`)];download(`techpath-journal-${today()}.md`,md.join('\n'));}
 document.addEventListener('input',e=>{const el=e.target;if(el.id.startsWith('draft-')){syncDraft();clearTimeout(saveTimer);saveTimer=setTimeout(save,300);}if(el.id==='custom-duration'){const n=Number(el.value);if(Number.isInteger(n)&&n>=15&&n<=240){state.duration=n;save();document.querySelectorAll('[data-duration]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.duration)===n));}}for(const [id,set] of [['lesson-search',v=>lessonSearch=v],['notebook-search',v=>notebookSearch=v],['vocab-search',v=>vocabSearch=v]])if(el.id===id){const pos=el.selectionStart;set(el.value);render();const n=$('#'+id);n.focus();n.setSelectionRange(pos,pos);}});
 document.addEventListener('keydown',e=>{if(e.target.id==='draft-code'&&e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('    ',start,end,'end');syncDraft();save();}});
 document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){draft(currentLesson().id).checks[Number(e.target.dataset.check)]=e.target.checked;syncDraft();save();}});
 document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.id==='modal-close')$('#modal').close();
  if(b.id==='open-tutor'||b.id==='open-tutor-top'||b.classList.contains('open-tutor-btn')){window.TechPathTutor.open(window.TechPathTutorContext());return;}
  if(b.id==='backup-top'||b.hasAttribute('data-backup'))backup();
  if(b.hasAttribute('data-run-sql')){try{await runInApp(currentLesson());}catch(error){toast(error.message);}return;}
  if(b.hasAttribute('data-stop-sql')){window.TechPathSql.stop();return;}
  if(b.hasAttribute('data-skip')){if(gradeBusy||sqlBusy||tutorBusy)return;syncDraft();const l=currentLesson();storeAttempt('skipped');moveOn(l.id,'Đã bỏ qua: '+l.title+'. Bài làm được giữ lại.');return;}
  if(b.hasAttribute('data-duration')){state.duration=Number(b.dataset.duration);save();render();}
  if(b.hasAttribute('data-filter')){moduleFilter=b.dataset.filter;history.replaceState(null,'','#lessons');render();}
  if(b.hasAttribute('data-start-session')){const n=Number($('#custom-duration')?.value||state.duration);if(!Number.isInteger(n)||n<15||n>240){toast('Chọn số phút nguyên từ 15 đến 240.');return;}if(!state.session){state.duration=n;state.session={id:uid(),lessonId:state.selected,duration:n,elapsed:0,running:true,started:Date.now()};save();}location.hash='session';render();}
  if(b.hasAttribute('data-lesson-tab')){syncDraft();save();lessonTab=b.dataset.lessonTab;render();}
  if(b.hasAttribute('data-hint')){syncDraft();const d=draft(currentLesson().id);d.hints=Math.min(d.hints+1,currentLesson().hints.length);save();render();}
  if(b.hasAttribute('data-transfer')){syncDraft();draft(currentLesson().id).mode='transfer';save();lessonTab='practice';render();}
  if(b.hasAttribute('data-solution')){syncDraft();draft(currentLesson().id).solution=true;save();render();$('#solution').open=true;}
  if(b.hasAttribute('data-copy-code'))copy(b.parentElement.querySelector('code').textContent);
  if(b.hasAttribute('data-seed'))download('SupportLab.sql',C.seed);
  if(b.hasAttribute('data-tutor'))copy(tutorPrompt);
  if(b.hasAttribute('data-download-code')){syncDraft();download(currentLesson().id+'.sql',draft(currentLesson().id).code);}
  if(b.hasAttribute('data-save-attempt')){storeAttempt();toast('Đã lưu mốc thực hành vào Nhật ký.');}
  if(b.hasAttribute('data-new-attempt')){syncDraft();const l=currentLesson(),d=draft(l.id);if(d.code||d.notes||d.output)storeAttempt();state.drafts[l.id]={code:'',output:'',notes:'',question:'',hints:0,solution:false,mode:d.mode,checks:[]};save();render();toast('Lần thử mới. Bài cũ đã giữ trong Nhật ký.');}
  if(b.hasAttribute('data-review')){await gradeAttempt();return;}
  if(b.hasAttribute('data-copy-packet'))copy(reviewPacket);
  if(b.hasAttribute('data-download-packet'))download('review-context.md',reviewPacket);

  if(b.hasAttribute('data-pause')){const s=state.session;if(s){s.elapsed=elapsed();s.running=!s.running;s.started=Date.now();save();render();}}
  if(b.hasAttribute('data-finish-session')){const s=state.session;if(!s)return;s.elapsed=elapsed();s.running=false;save();showModal('Khép lại buổi học',`<p>${Math.floor(s.elapsed/60000)} phút tập trung. Bài học vẫn giữ nguyên để tiếp tục lần sau.</p><label for="session-reflection">Một điều đã hiểu và một điều cần ôn</label><textarea id="session-reflection" placeholder="Mình đã hiểu… Buổi sau cần…"></textarea><button class="button" data-confirm-finish>Lưu và kết thúc</button>`);}
  if(b.hasAttribute('data-confirm-finish')){const s=state.session;if(!s)return;state.sessions.push({id:s.id,at:new Date().toISOString(),lessonId:s.lessonId,planned:s.duration,minutes:Math.floor(s.elapsed/60000),reflection:$('#session-reflection').value});state.session=null;save();$('#modal').close();location.hash='notebook';render();toast('Đã lưu buổi học.');}
  if(b.hasAttribute('data-add-note')){const t=$('#quick-note').value.trim();if(!t){toast('Ghi một điều muốn lưu trước nhé.');return;}state.notes.push({id:uid(),at:new Date().toISOString(),text:t});save();render();toast('Đã lưu ghi chú.');}
  if(b.hasAttribute('data-export-md'))exportMd();
  if(b.hasAttribute('data-import'))$('#import-file').click();
  if(b.hasAttribute('data-import-sql')){const f=document.createElement('input');f.type='file';f.accept='.sql,text/plain';f.onchange=async()=>{const file=f.files[0];if(!file)return;if(file.size>1000000){toast('Chọn file SQL nhỏ hơn 1 MB.');return;}const bytes=await file.arrayBuffer();const a=new Uint8Array(bytes);const decoder=new TextDecoder(a[0]===255&&a[1]===254?'utf-16le':a[0]===254&&a[1]===255?'utf-16be':'utf-8');const text=decoder.decode(bytes);syncDraft();draft(currentLesson().id).code=text;save();render();toast('Đã nhập code. File chỉ được đọc, không thực thi.');};f.click();}
 });
 $('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>15000000){toast('File sao lưu phải nhỏ hơn 15 MB.');return;}try{const next=validate(JSON.parse(await f.text()));if(next.session){next.session.elapsed=next.session.elapsed+(next.session.running?Math.max(0,Date.now()-next.session.started):0);next.session.running=false;}showModal('Nhập tiến độ từ thiết bị khác',`<p>File có ${next.attempts.length} lần thử, ${next.sessions.length} buổi học và ${next.notes.length} ghi chú. Nhập sẽ thay thế dữ liệu hiện tại (${state.attempts.length} lần thử). File chỉ chứa dữ liệu, không thực thi code.</p><button class="button secondary" id="backup-before-import">1. Tải bản sao hiện tại</button><button class="button" id="confirm-import" disabled>2. Thay thế bằng file đã chọn</button>`);$('#backup-before-import').onclick=()=>{backup();$('#confirm-import').disabled=false;};$('#confirm-import').onclick=()=>{state=next;if(next.tutor)window.TechPathTutor?.restore(next.tutor);save();$('#modal').close();render();toast('Đã nhập tiến độ. Đồng hồ được tạm dừng.');};}catch(err){toast('Không nhập được: '+err.message);}});
 window.addEventListener('techpath:tutor-busy',event=>{tutorBusy=!!event.detail;updateWorkControls();});
 document.addEventListener('keydown',event=>{if(event.target.id==='draft-code'&&event.key==='Enter'&&(event.ctrlKey||event.metaKey)&&currentLesson().module==='sql'){event.preventDefault();if(!sqlBusy&&!gradeBusy&&!tutorBusy)runInApp(currentLesson()).catch(error=>toast(error.message));}});
 window.addEventListener('hashchange',()=>{syncDraft();save();lessonTab='learn';render();window.scrollTo(0,0);});
 window.addEventListener('pagehide',()=>{syncDraft();if(state.session){state.session.elapsed=elapsed();state.session.started=Date.now();}save();});
 setInterval(()=>{if($('#timer'))$('#timer').textContent=formatTime(elapsed());},1000);
 let lastHostLesson=null,hostConnected=!!window.TechPathHost?.available(),hostHydrated=false;
 function applyHostContext(){
  if(!window.TechPathHost)return;
  if(!hostHydrated){const snapshot=window.TechPathHost.state();if(snapshot&&!hadLocalState){try{state=validate(snapshot);hostHydrated=true;}catch{}}}
  const context=window.TechPathHost.context();
  if(context?.lesson_id&&validIds.has(context.lesson_id)&&context.lesson_id!==lastHostLesson){lastHostLesson=context.lesson_id;syncDraft();state.selected=context.lesson_id;save();location.hash='lesson/'+context.lesson_id;render();return;}
  const connected=window.TechPathHost.available();if(connected!==hostConnected){hostConnected=connected;render();}
 }
 window.addEventListener('techpath:host',applyHostContext);
 render();applyHostContext();
 // Expose only pure validation/planning helpers to local checks, never credentials.
 window.TechPathDebug={validate,planBlocks,status,lessonCount:C.lessons.length};
})();
